// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function testFuzz_property(address owner0, address actor) public {
        // Owner defaults to address(0); transferOwnership from there to set a fuzzed owner.
        vm.assume(owner0 != address(0));
        vm.prank(address(0));
        c.transferOwnership(owner0);

        bool ok;
        vm.prank(actor);
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: owned() succeeds if and only if the caller is the current owner.
        assertTrue(ok == (actor == c.owner()));
    }
}
